def transform_debug(grid, debug=True):
    """Transform the grid - odd image count → 5, even → 1"""
    if not grid or not grid[0]:
        return grid

    n_rows = len(grid)
    n_cols = len(grid[0])

    # Find separator value
    row_constants = {}
    for i, row in enumerate(grid):
        if len(set(row)) == 1:
            val = row[0]
            row_constants[val] = row_constants.get(val, 0) + 1

    separator_value = max(row_constants.keys(), key=lambda v: row_constants[v]) if row_constants else None

    print(f"Separator value: {separator_value}")

    # Find separator row indices
    separator_rows = sorted([i for i, row in enumerate(grid) if all(x == separator_value for x in row)])
    print(f"Separator rows: {separator_rows}")

    # Find separator col indices
    separator_cols = sorted([j for j in range(n_cols) if all(grid[i][j] == separator_value for i in range(n_rows))])
    print(f"Separator cols: {separator_cols}")

    # Determine which region each cell is in
    def get_region_row(r):
        return sum(1 for s in separator_rows if r >= s)

    def get_region_col(c):
        return sum(1 for s in separator_cols if c >= s)

    # Count 2s per region
    region_counts = {}
    for r in range(n_rows):
        for c in range(n_cols):
            if grid[r][c] == 2:
                reg = (get_region_row(r), get_region_col(c))
                region_counts[reg] = region_counts.get(reg, 0) + 1

    # Build output grid
    max_r = max([r[0] for r in region_counts.keys()], default=0)
    max_c = max([r[1] for r in region_counts.keys()], default=0)

    if debug:
        print(f"Region dimensions: {max_r+1} x {max_c+1}")

    result = []
    for r in range(max_r + 1):
        row_result = []
        for c in range(max_c + 1):
            reg = (r, c)
            count = region_counts.get(reg, 0)
            if count % 2 == 1:
                row_result.append(5)
            else:
                row_result.append(1)
        result.append(row_result)

    print(f"Output: {result}")

    return result

